SELECT media.id_record,media.ghost_url::text AS ghost_url FROM public.record_media media LEFT JOIN public.record_statistic statistic ON statistic.id_record=media.id_record WHERE media.ghost_url IS NOT NULL AND (cardinality($1::integer[])=0 OR media.id_record=ANY($1)) AND (cardinality($1::integer[])>0 OR $2::integer IS NULL OR media.id_record<$2) AND (cardinality($1::integer[])>0 OR ( ($3::integer IS NOT NULL AND statistic.ghost_version=$3) OR ($3::integer IS NULL AND (statistic.id_record IS NULL OR statistic.ghost_version IS NULL OR statistic.has_input_data IS NULL OR statistic.has_air_data IS NULL OR statistic.has_wheel_data IS NULL OR statistic.has_slip_data IS NULL OR statistic.has_state_data IS NULL OR statistic.has_surface_data IS NULL OR statistic.has_velocity_data IS NULL OR statistic.has_ragdoll_data IS NULL OR (statistic.has_input_data=true AND (statistic.time_any_driver_input IS NULL OR statistic.driver_input_transition_count IS NULL)))))) ORDER BY media.id_record DESC LIMIT $4
